use xiom.io;
fn is_prime(n: Int) -> Bool {
  if n < 2 { return false; };
  let mut i = 2;
  while i * i <= n {
    if n % i == 0 { return false; };
    i += 1;
  };
  true
}

fn generate_primes(count: Int) -> Vec[Int] {
  let mut primes: Vec[Int] = Vec[Int].new();
  let mut candidate = 2;
  while primes.len() < count {
    if is_prime(candidate) {
      primes.push(candidate);
    };
    candidate += 1;
  };
  primes
}

fn main() -> Int {
  let primes = generate_primes(15);
  let mut i = 0;
  while i < primes.len() {
    io.println(primes.get(i).unwrap().to_str());
    i += 1;
  };
  return 0;
}
